Contract AutomatedTellerMachineSystem::printReceipt(): Real {

            precondition:
          InputCard.oclIsUndefined() = false and InputCard.CardStatus = BankCard::NORMAL and InputCard.Balance >= WithdrawedNumber

            postcondition:
          let receipt:BankCard in receipt.oclIsNew(), InputCard.Balance = InputCard.Balance - WithdrawedNumber, result = WithdrawedNumber

        }

Contract ManageSupplierCRUDService::createSupplier(id:Integer,name:String): Boolean {

            precondition:
          id <> null and name <> null and id > 0 and name.size() > 0 and Supplier.allInstance()->excludes(s | s.Id = id)

            postcondition:
          let s:Supplier in s.oclIsNew(), Supplier.allInstance()->includes(s), s.Id = id and s.Name = name, result = true

        }
